arguments.command:
$filePath = "X:\code\copilot-worktrees\P09\cirvine-msft-ubiquitous-carnival\assets\undo.txt"

# Read file as raw text
$content = [System.IO.File]::ReadAllText($filePath)
$lines = $content -split "`n" | Where-Object {$_}  # Split and remove empty trailing line

# Verify constraints
Write-Host "=== VERIFICATION RESULTS ===" -ForegroundColor Cyan
Write-Host ""

# 1. Line count
Write-Host "Line count: $($lines.Count)" -ForegroundColor Yellow
if ($lines.Count -eq 12) {
  Write-Host "✓ PASS: Exactly 12 lines" -ForegroundColor Green
} else {
  Write-Host "✗ FAIL: Expected 12 lines, got $($lines.Count)" -ForegroundColor Red
}

# 2. Line lengths and trailing whitespace
Write-Host ""
Write-Host "Line lengths and trailing whitespace check:" -ForegroundColor Yellow
$allLengthsValid = $true
$anyTrailing = $false
for ($i = 0; $i -lt $lines.Count; $i++) {
  $line = $lines[$i]
  $len = $line.Length
  $hasTrailing = $line -match '\s+$'

  $status = if ($len -ge 20 -and $len -le 48 -and -not $hasTrailing) { "✓" } else { "✗" }
  $trailingMsg = if ($hasTrailing) { " [HAS TRAILING SPACE]" } else { "" }
  Write-Host "  Line $($i+1): Length $len$trailingMsg $status"

  if ($len -lt 20 -or $len -gt 48) { $allLengthsValid = $false }
  if ($hasTrailing) { $anyTrailing = $true }
}

if ($allLengthsValid -and -not $anyTrailing) {
  Write-Host "✓ PASS: All lines 20-48 chars, no trailing whitespace" -ForegroundColor Green
} else {
  Write-Host "✗ FAIL: Some lines fail length/trailing checks" -ForegroundColor Red
}

# 3. Allowed characters check
Write-Host ""
Write-Host "Character validation:" -ForegroundColor Yellow
$allowedChars = @(' ', 'A'..'Z', '0'..'9', '+', '|', '/', '\', '_', '*', '.', '#', '(', ')', ':', '=', '-', "`n")
$allowedPattern = '[^A-Z0-9+|/\\_\*\.#\(\):=\-\s]'

$invalidChars = $content | Select-String -Pattern $allowedPattern -AllMatches
if ($null -eq $invalidChars) {
  Write-Host "✓ PASS: Only allowed characters (A-Z, 0-9, space, +|/\\_*\.#():=-, newline)" -ForegroundColor Green
} else {
  Write-Host "✗ FAIL: Invalid characters found: $($invalidChars.Matches.Value | Select-Object -Unique)" -ForegroundColor Red
}

# 4. Contains "UNDO"
Write-Host ""
Write-Host "UNDO substring check:" -ForegroundColor Yellow
if ($content -like "*UNDO*") {
  Write-Host "✓ PASS: Contains literal 'UNDO'" -ForegroundColor Green
} else {
  Write-Host "✗ FAIL: Does not contain 'UNDO'" -ForegroundColor Red
}

# 5. Ends with exactly one newline
Write-Host ""
Write-Host "File ending check:" -ForegroundColor Yellow
$endsWithNewline = $content -match "`n$"
if ($endsWithNewline) {
  Write-Host "✓ PASS: Ends with exactly one newline" -ForegroundColor Green
} else {
  Write-Host "✗ FAIL: Does not end with newline" -ForegroundColor Red
}

# Display the file
Write-Host ""
Write-Host "=== FILE CONTENT ===" -ForegroundColor Cyan
Write-Host $content

